-- READ ONLY. Part of the hosted test-data cleanup (tools/sql/cleanup/README.md).
-- 03: after the cleanup. Expect: no candidate rows left for the test tenants except in tables the cleanup reported as skipped;
-- the kept tables still hold their rows; the three tenants still exist.
select 'test tenants still exist' as check, case when (select count(*) from app.tenant where slug = any(ARRAY['test-dsa-alpha', 'test-dsa-beta', 'test-tenant-b'])) = 3 then 'PASS' else 'FAIL' end as result
union all select 'users and roles of the test tenants are untouched (more than zero)',
       case when (select count(*) from app.app_user where tenant_id in (select id from app.tenant where slug = any(ARRAY['test-dsa-alpha', 'test-dsa-beta', 'test-tenant-b']))) > 0
             and (select count(*) from app.role where tenant_id in (select id from app.tenant where slug = any(ARRAY['test-dsa-alpha', 'test-dsa-beta', 'test-tenant-b']))) > 0 then 'PASS' else 'FAIL' end
union all select 'other tenants are untouched (demo, platform): their users still exist',
       case when (select count(*) from app.app_user where tenant_id in (select id from app.tenant where slug not in ('test-dsa-alpha', 'test-dsa-beta', 'test-tenant-b'))) > 0 then 'PASS' else 'FAIL' end
union all select 'left in activity for the test tenants', (select count(*)::text from app.activity where tenant_id in (select id from app.tenant where slug = any(ARRAY['test-dsa-alpha', 'test-dsa-beta', 'test-tenant-b'])))
union all select 'left in message_template for the test tenants', (select count(*)::text from app.message_template where tenant_id in (select id from app.tenant where slug = any(ARRAY['test-dsa-alpha', 'test-dsa-beta', 'test-tenant-b'])))
